bool UFoundrylineEmployeeVisualComponent::InitializeHandyman(){
 if(!Appearance||!Appearance->Mesh||!Appearance->Idle||!Appearance->Walk)return false;
 if(Appearance->RuntimeVariants.IsEmpty()&&!Appearance->Outfits.IsEmpty()){for(int I=0;I<Appearance->Outfits.Num();++I){TArray<USkeletalMesh*> Parts;for(auto P:Appearance->Outfits[I].Parts)Parts.Add(P.Get());auto* M=UFoundrylineHandymanAssetTools::BuildRuntimeVariant(I,Parts);if(!M){Appearance->RuntimeVariants.Reset();return false;}Appearance->RuntimeVariants.Add(M);}}
 auto* Mesh=Appearance->Mesh.Get();const auto& Ref=Mesh->GetRefSkeleton();for(int I=0;I<Ref.GetNum();++I){const int P=Ref.GetParentIndex(I);FTransform T=Ref.GetRefBonePose()[I];if(P>=0)T*=HandymanRest[P];HandymanRest.Add(T);HandymanParents.Add(P);HandymanBones.Add(Ref.GetBoneName(I),I);}
 for(FName N:{TEXT("pelvis"),TEXT("thigh_l"),TEXT("calf_l"),TEXT("foot_l"),TEXT("upperarm_l"),TEXT("lowerarm_l"),TEXT("hand_l"),TEXT("hand_r")})if(!HandymanBones.Contains(N))return false;
 SkeletalBody=NewObject<USkeletalMeshComponent>(GetOwner(),MakeUniqueObjectName(GetOwner(),USkeletalMeshComponent::StaticClass(),TEXT("EmployeeAnimationSource")));SkeletalBody->SetupAttachment(this);SkeletalBody->SetSkeletalMeshAsset(Mesh);SkeletalBody->SetRelativeLocationAndRotation(Appearance->FootRootOffset,Appearance->FacingOffset);SkeletalBody->SetCollisionEnabled(ECollisionEnabled::NoCollision);SkeletalBody->SetCanEverAffectNavigation(false);SkeletalBody->SetAnimationMode(EAnimationMode::AnimationSingleNode);SkeletalBody->VisibilityBasedAnimTickOption=EVisibilityBasedAnimTickOption::AlwaysTickPoseAndRefreshBones;SkeletalBody->ComponentTags.Add(TEXT("EmployeeAnimationSampler"));SkeletalBody->SetVisibility(false);SkeletalBody->SetHiddenInGame(true);SkeletalBody->SetCastShadow(false);SkeletalBody->RegisterComponent();SkeletalBody->SetComponentTickEnabled(false);GetOwner()->AddInstanceComponent(SkeletalBody);
 HandymanBody=NewObject<UPoseableMeshComponent>(GetOwner(),MakeUniqueObjectName(GetOwner(),UPoseableMeshComponent::StaticClass(),TEXT("EmployeeHandyman")));HandymanBody->SetupAttachment(this);HandymanBody->SetSkinnedAssetAndUpdate(Mesh);HandymanBody->SetRelativeLocationAndRotation(Appearance->FootRootOffset,Appearance->FacingOffset);HandymanBody->SetCollisionEnabled(ECollisionEnabled::NoCollision);HandymanBody->SetCanEverAffectNavigation(false);HandymanBody->SetBoundsScale(2);HandymanBody->ComponentTags.Add(TEXT("EmployeeHandyman"));HandymanBody->RegisterComponent();GetOwner()->AddInstanceComponent(HandymanBody);
 for(int I=0;I<2;++I){const int H=HandymanBones.FindRef(I?TEXT("hand_r"):TEXT("hand_l")),M=HandymanBones.FindRef(I?TEXT("middle_01_r"):TEXT("middle_01_l"));HandymanPalmOffsets[I]=HandymanRest[H].InverseTransformPosition(FMath::Lerp(HandymanRest[H].GetLocation(),HandymanRest[M].GetLocation(),.55));}
 return true;
}
void UFoundrylineEmployeeVisualComponent::HandymanRotate(int32 Bone,FQuat Delta){
 if(!HandymanPose.IsValidIndex(Bone))return;const FVector Pivot=HandymanPose[Bone].GetLocation();for(int I=Bone;I<HandymanPose.Num();++I){int P=I;while(P>Bone)P=HandymanParents[P];if(P!=Bone)continue;auto& T=HandymanPose[I];T.SetLocation(Pivot+Delta.RotateVector(T.GetLocation()-Pivot));T.SetRotation((Delta*T.GetRotation()).GetNormalized());}
}
void UFoundrylineEmployeeVisualComponent::HandymanIK(FName Upper,FName Lower,FName End,FVector Target,FVector Pole,const FQuat* EndRotation){
 if(!HandymanBones.Contains(Upper)||!HandymanBones.Contains(Lower)||!HandymanBones.Contains(End))return;const int A=HandymanBones[Upper],B=HandymanBones[Lower],C=HandymanBones[End];const FVector Start=HandymanPose[A].GetLocation();const double L1=FVector::Distance(HandymanPose[B].GetLocation(),Start),L2=FVector::Distance(HandymanPose[C].GetLocation(),HandymanPose[B].GetLocation());FVector D=Target-Start;double Len=FMath::Clamp(D.Size(),FMath::Abs(L1-L2)+.01,L1+L2-.01);D=D.GetSafeNormal();FVector Bend=FVector::VectorPlaneProject(Pole-Start,D).GetSafeNormal();if(Bend.IsNearlyZero())Bend=FVector::CrossProduct(D,FVector::RightVector).GetSafeNormal();const double Along=(L1*L1-L2*L2+Len*Len)/(2*Len);const FVector Joint=Start+D*Along+Bend*FMath::Sqrt(FMath::Max(0.,L1*L1-Along*Along));HandymanRotate(A,FQuat::FindBetweenVectors(HandymanPose[B].GetLocation()-Start,Joint-Start));HandymanRotate(B,FQuat::FindBetweenVectors(HandymanPose[C].GetLocation()-HandymanPose[B].GetLocation(),Start+D*Len-HandymanPose[B].GetLocation()));if(EndRotation)HandymanRotate(C,(*EndRotation*HandymanPose[C].GetRotation().Inverse()).GetNormalized());
}
void UFoundrylineEmployeeVisualComponent::HandymanPalm(int32 I,FVector Palm,bool Grip){
 if(!HandymanBody||HandymanPose.IsEmpty())return;const FTransform T=HandymanBody->GetRelativeTransform();const FName H=I?TEXT("hand_r"):TEXT("hand_l");const int Index=HandymanBones.FindRef(H);const FVector Dir=T.InverseTransformVectorNoScale(Grip?FVector(1,0,.25):FVector(1,0,-.1)).GetSafeNormal();const FVector RefDir=HandymanRest[Index].GetRotation().RotateVector(HandymanPalmOffsets[I]).GetSafeNormal();FQuat Rotation=FQuat::FindBetweenVectors(RefDir,Dir)*HandymanRest[Index].GetRotation();FVector Wrist=T.InverseTransformPosition(Palm)-Rotation.RotateVector(HandymanPalmOffsets[I]);const FVector Pole=T.InverseTransformPosition(FVector(12,I?50:-50,bSeated?150:110));HandymanIK(I?TEXT("upperarm_r"):TEXT("upperarm_l"),I?TEXT("lowerarm_r"):TEXT("lowerarm_l"),H,Wrist,Pole,&Rotation);
}
void UFoundrylineEmployeeVisualComponent::CommitHandymanPose(){
 if(!HandymanBody||HandymanPose.Num()!=HandymanParents.Num())return;HandymanBody->BoneSpaceTransforms.SetNum(HandymanPose.Num());for(int I=0;I<HandymanPose.Num();++I)HandymanBody->BoneSpaceTransforms[I]=HandymanParents[I]>=0?HandymanPose[I].GetRelativeTransform(HandymanPose[HandymanParents[I]]):HandymanPose[I];HandymanBody->MarkRefreshTransformDirty();HandymanBody->RefreshBoneTransforms();HandymanBody->UpdateBounds();
}
void UFoundrylineEmployeeVisualComponent::PresentCollectorGrip(FVector Left,FVector Right){
 if(!HandymanBody||HandymanPose.IsEmpty())return;
 const FVector LocalRight=GetComponentTransform().InverseTransformPosition(Right);
 const float Lean=FMath::Clamp(float((99-LocalRight.Z)/15),0.f,1.f)*35.f;
 if(Lean>0&&HandymanBones.Contains(TEXT("spine_01")))HandymanRotate(HandymanBones[TEXT("spine_01")],FQuat(HandymanBody->GetRelativeTransform().InverseTransformVectorNoScale(FVector::RightVector),FMath::DegreesToRadians(Lean)));
 HandymanPalm(0,GetComponentTransform().InverseTransformPosition(Left),true);
 HandymanPalm(1,GetComponentTransform().InverseTransformPosition(Right),true);CommitHandymanPose();
}
void UFoundrylineEmployeeVisualComponent::PresentHandyman(const FFoundrylineEmployeeRecord& R,float Dt){
 // Vehicle visibility propagates to its descendants. This component samples animation
 // only; never render it alongside the independently posed employee in the seat.
 if(SkeletalBody){SkeletalBody->SetVisibility(false);SkeletalBody->SetHiddenInGame(true);}
 const auto& Variants=Appearance->RuntimeVariants.IsEmpty()?Appearance->Variants:Appearance->RuntimeVariants;
 if(HandymanVariant<0)HandymanVariant=Variants.IsEmpty()?0:int(FCrc::StrCrc32(*R.Key)%Variants.Num());
 USkeletalMesh* DesiredMesh=Variants.IsValidIndex(HandymanVariant)?Variants[HandymanVariant].Get():Appearance->Mesh.Get();
 bWeldingHoodBody=false;
 if(UFoundrylineWeldingHoodComponent::WantsHood(R)&&GetOwner()->GetNetMode()!=NM_DedicatedServer){
  if(!WeldingHood){WeldingHood=NewObject<UFoundrylineWeldingHoodComponent>(GetOwner());WeldingHood->SetupAttachment(this);WeldingHood->RegisterComponent();GetOwner()->AddInstanceComponent(WeldingHood);}
  if(WeldingHood->HasModelAssets())if(auto* NoHat=UFoundrylineWeldingHoodComponent::NoHatOutfit(Appearance,HandymanVariant)){DesiredMesh=NoHat;bWeldingHoodBody=true;}
 }
 if(HandymanBody->GetSkinnedAsset()!=DesiredMesh){auto* Mesh=DesiredMesh;HandymanBody->SetSkinnedAssetAndUpdate(Mesh);HandymanRest.Reset();HandymanParents.Reset();HandymanBones.Reset();HandymanSamplerBones.Reset();const auto& Ref=Mesh->GetRefSkeleton();for(int I=0;I<Ref.GetNum();++I){const int P=Ref.GetParentIndex(I);FTransform T=Ref.GetRefBonePose()[I];if(P>=0)T*=HandymanRest[P];HandymanRest.Add(T);HandymanParents.Add(P);HandymanBones.Add(Ref.GetBoneName(I),I);HandymanSamplerBones.Add(SkeletalBody->GetBoneIndex(Ref.GetBoneName(I)));}for(int I=0;I<2;++I){const int H=HandymanBones.FindRef(I?TEXT("hand_r"):TEXT("hand_l")),M=HandymanBones.FindRef(I?TEXT("middle_01_r"):TEXT("middle_01_l"));HandymanPalmOffsets[I]=HandymanRest[H].InverseTransformPosition(FMath::Lerp(HandymanRest[H].GetLocation(),HandymanRest[M].GetLocation(),.55));}}
 if(R.Activity!=EFoundrylineEmployeeActivity::Paused)HandymanClock+=FMath::Min(Dt,.1f);auto* Clip=R.bMoving&&!R.bSeated?Appearance->Walk.Get():Appearance->Idle.Get();HandymanAnimation=Clip->GetPathName();if(!SkeletalBody->GetSingleNodeInstance()||SkeletalBody->GetSingleNodeInstance()->GetCurrentAsset()!=Clip)SkeletalBody->SetAnimation(Clip);SkeletalBody->SetPlayRate(0);const float Time=R.bMoving&&!R.bSeated?Phase*Clip->GetPlayLength():FMath::Fmod(HandymanClock,Clip->GetPlayLength());SkeletalBody->SetPosition(Time,false);SkeletalBody->TickAnimation(0,false);SkeletalBody->RefreshBoneTransforms();const auto& Evaluated=SkeletalBody->GetComponentSpaceTransforms();HandymanPose.SetNum(HandymanParents.Num());for(int I=0;I<HandymanPose.Num();++I){const int Source=HandymanSamplerBones.IsValidIndex(I)?HandymanSamplerBones[I]:INDEX_NONE;HandymanPose[I]=Evaluated.IsValidIndex(Source)?Evaluated[Source]:HandymanRest[I];}
 const FTransform T=HandymanBody->GetRelativeTransform();
 if(bSeated||R.bMoving){const int Pel=HandymanBones.FindRef(TEXT("pelvis"));const FVector Shift=T.InverseTransformVectorNoScale(FVector(0,0,bSeated?147:86))-HandymanPose[Pel].GetLocation();for(int I=Pel;I<HandymanPose.Num();++I){int P=I;while(P>Pel)P=HandymanParents[P];if(P==Pel)HandymanPose[I].AddToTranslation(Shift);}if(bSeated){const int Spine=HandymanBones.FindRef(TEXT("spine_02"));HandymanRotate(Spine,FQuat(T.InverseTransformVectorNoScale(FVector::RightVector),FMath::DegreesToRadians(9.f)));}}
 // The imported hip sway can put the far stance a few millimetres beyond a straight leg.
 // Lower the pelvis only by the anatomical reach deficit; never stretch a bone or lift a planted sole.
 if(R.bMoving&&!bSeated){double Drop=0;for(int I=0;I<2;++I){const float P=FMath::Fmod(Phase+I*.5f,1.f);float X,Z=8.23821;if(P<.5f)X=27.5f-110*P;else{const float A=(P-.5f)*2;X=FMath::Lerp(-27.5f,27.5f,A);Z+=10*FMath::Sin(PI*A);}const FVector Target(X,I?14.08756:-14.08756,Z);const int A=HandymanBones.FindRef(I?TEXT("thigh_r"):TEXT("thigh_l")),B=HandymanBones.FindRef(I?TEXT("calf_r"):TEXT("calf_l")),C=HandymanBones.FindRef(I?TEXT("foot_r"):TEXT("foot_l"));const FVector Hip=T.TransformPosition(HandymanPose[A].GetLocation());const double Reach=FVector::Distance(HandymanPose[A].GetLocation(),HandymanPose[B].GetLocation())+FVector::Distance(HandymanPose[B].GetLocation(),HandymanPose[C].GetLocation())-.1;const double Horizontal=FVector::DistSquared2D(Hip,Target);const double Height=FMath::Sqrt(FMath::Max(0.,Reach*Reach-Horizontal));Drop=FMath::Max(Drop,Hip.Z-Target.Z-Height);}if(Drop>0){const int Pel=HandymanBones.FindRef(TEXT("pelvis"));const FVector Shift=T.InverseTransformVectorNoScale(FVector(0,0,-FMath::Min(Drop,3.)));for(int I=Pel;I<HandymanPose.Num();++I){int P=I;while(P>Pel)P=HandymanParents[P];if(P==Pel)HandymanPose[I].AddToTranslation(Shift);}}}
 for(int I=0;I<2;++I){const FName Foot=I?TEXT("foot_r"):TEXT("foot_l");const int F=HandymanBones.FindRef(Foot);if(R.bMoving&&!bSeated||bSeated){float X=0,Z=8.23821;const float P=FMath::Fmod(Phase+I*.5f,1.f);if(bSeated){X=47;Z+=83;}else if(P<.5f)X=27.5f-110*P;else{const float A=(P-.5f)*2;X=FMath::Lerp(-27.5f,27.5f,A);Z+=10*FMath::Sin(PI*A);}const FVector Target=T.InverseTransformPosition({X,I?14.08756:-14.08756,Z});const FVector Pole=T.InverseTransformPosition({100,I?15.:-15.,bSeated?125.:40.});const FQuat Rotation=HandymanRest[F].GetRotation();HandymanIK(I?TEXT("thigh_r"):TEXT("thigh_l"),I?TEXT("calf_r"):TEXT("calf_l"),Foot,Target,Pole,&Rotation);}}
 if(bSeated){HandymanPalm(0,{43,-18,174},true);HandymanPalm(1,{43,18,174},true);}else if(R.bWorking){const int Spine=HandymanBones.FindRef(TEXT("spine_02"));HandymanRotate(Spine,FQuat(T.InverseTransformVectorNoScale(FVector::RightVector),FMath::DegreesToRadians(R.Assignment==2?15.f:R.Assignment==3?12.f:7.f)));if(R.Activity==EFoundrylineEmployeeActivity::Welding){HandymanPalm(0,{49,-3,131},true);HandymanPalm(1,{43,0,125},true);}else{const float Reach=R.Assignment==2?55.f:R.Assignment==3?50.f:42.f;const float Tap=R.bWorking?FMath::Sin(WorkPhase*6*PI):0;HandymanPalm(0,{Reach,-12,115+Tap});HandymanPalm(1,{Reach,12,115-Tap});}}
 CommitHandymanPose();
 if(WeldingHood)WeldingHood->Present(HandymanBody,R,bWeldingHoodBody,Dt);
}
